      "audio": {
        "speaker_id": "spk1",
        "asr_text": "...",
        "mode": "asr",
        "acoustic_events": ["..."]
      }
    }
  ],
  "global_description": {
    "scene": "...",
    "narrative": "...",
    "caption": "...",
    "tag": "..."
  },
  "structured_report": {}
}
```
